head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gSeq;
scwin.gIsurCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF36001.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Insert = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    if (vIsurCd.length != 5) {
        $c.win.alert("회사코드를 입력하세요.");
        txb_isur_cd.focus();
        return;
    }
    var vHaltschdlDd = $c.stf.getObjectValue(edt_haltschdl_dd);
    if (vHaltschdlDd.length > 0 && vHaltschdlDd.length < 8) {
        $c.win.alert("매매거래정지예정일을 올바르게 입력하시오.");
        edt_haltschdl_dd.focus();
        return;
    }
    var vReleasDd = $c.stf.getObjectValue(edt_releas_dd);
    if (vReleasDd > 0 && vReleasDd.length < 8) {
        $c.win.alert("매매거래해제예정일을 올바르게 입력하시오.");
        edt_releas_dd.focus();
        return;
    }
    var vNewschdlDd = $c.stf.getObjectValue(edt_newschdl_dd);
    if (vNewschdlDd > 0 && vNewschdlDd.length < 8) {
        $c.win.alert("신주권교부예정일을 올바르게 입력하시오.");
        edt_newschdl_dd.focus();
        return;
    }
    var vListschdlDd = $c.stf.getObjectValue(edt_listschdl_dd);
    if (vListschdlDd > 0 && vListschdlDd.length < 8) {
        $c.win.alert("상장예정일을 올바르게 입력하시오.");
        edt_listschdl_dd.focus();
        return;
    }
    dts_haltschdl.insertRow();
    dts_haltschdl.setCellData(1, "ISUR_CD", vIsurCd);
    dts_haltschdl.setCellData(1, "HALT_SCHDL_DD", vHaltschdlDd);
    dts_haltschdl.setCellData(1, "HALT_RELEAS_SCHDL_DD", vReleasDd);
    dts_haltschdl.setCellData(1, "NEWSTK_SCHDL_DD", vNewschdlDd);
    dts_haltschdl.setCellData(1, "LIST_SCHDL_DD", vListschdlDd);
    dts_haltschdl.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));
    //alert(dts_nfaith.text);

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_haltschdl.Action = "/TrdHaltSchdl.do?method=registerTrdHaltSchdl&inputMessageId=HALTSCHDLINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_haltschdl.KeyName = "toinb_dataid4";
        trs_haltschdl.KeyValue = "JSP(I:pInput=dts_haltschdl)";
        trs_haltschdl.Post();
    }
};
scwin.img_haltschdl_dd_onclick = function() {
    popUpCalendar2(edt_haltschdl_dd);
};
scwin.img_releas_dd_onclick = function() {
    popUpCalendar2(edt_releas_dd);
};
scwin.img_newschdl_dd_onclick = function() {
    popUpCalendar2(edt_newschdl_dd);
};
scwin.img_listschdl_dd_onclick = function() {
    popUpCalendar2(edt_listschdl_dd);
};
scwin.img_save_onclick = function() {
    scwin.fn_Insert();
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_haltschdl_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_haltschdl_OnFail = function() {
    $c.win.alert('trs_haltschdl.OnFail() :' + trs_haltschdl.ErrorMsg);
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);

    // 가우스헤더 셋팅
    dts_haltschdl.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=HALTSCHDLINFO_INOUT";
    dts_haltschdl.reset();
};
